from pathlib import Path
import html
root=Path(__file__).parent/'dist'
nav='''<header><a class="brand" href="/" aria-label="Lunar4 home"><span class="brand-logo"><img src="/lunar4-logo.png" alt="Lunar4" width="1254" height="1254"></span><span class="group-name">Music Group</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation"><a href="/hall-of-fame">Hall of Fame</a><a href="/channels">Channels</a><a href="/merch">Merch</a><a href="/articles">Articles</a><a href="/contact">Contact</a><a class="button" href="/submit-demo">Submit Demo</a></nav></header>'''
footer='''<footer class="wrap"><div class="footer-grid"><div><a class="brand" href="/"><span class="brand-logo"><img src="/lunar4-logo.png" alt="Lunar4" width="1254" height="1254"></span><span class="group-name">Music Group</span></a><p>Independent sounds. Shared everywhere.</p></div><div><h4>Explore</h4><a href="/">Home</a><a href="/hall-of-fame">Hall of Fame</a><a href="/channels">Channels</a><a href="/articles">Articles</a><a href="/contact">Contact</a></div><div><h4>Get in touch</h4><a href="/submit-demo">Submit your demo</a><a href="/privacy-policy">Privacy Policy</a><a href="/terms-of-service">Terms of Service</a></div></div><div class="copyright">© 2026 Lunar4. All rights reserved.</div></footer>'''
cta='''<section class="cta"><div class="eyebrow">Your next favourite sound</div><h2>Good music deserves<br>to be heard.</h2><p>Bring your sound to Lunar4. Your next chapter starts with a song.</p><a class="button" href="/submit-demo">Submit your demo <span>↗</span></a></section>'''
def head(title,sub='',mark=False):
 return '<section class="page-head wrap">'+('<div class="brand"><span class="brand-logo"><img src="/lunar4-logo.png" alt="Lunar4" width="1254" height="1254"></span></div>' if mark else '')+f'<h1>{title}</h1>'+ (f'<p>{sub}</p>' if sub else '')+'</section>'
def write(route,title,content,with_cta=True):
 p=root/route/'index.html' if route else root/'index.html';p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | Lunar4</title><meta name="description" content="Lunar4 — independent music, artist stories and demo submissions."><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%230a0a0a'/%3E%3Ctext x='7' y='24' font-size='24' font-family='Arial' font-weight='bold' fill='white'%3EL%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="/style.css"><script src="/config.js" defer></script><script src="/app.js" defer></script></head><body>{nav}<main>{content}</main>{cta if with_cta else ''}{footer}</body></html>''')
form='''<form class="form-card" id="demo-form"><div class="form-heading"><h3>Lunar4 Submission Portal</h3><p>Send us the track you want the world to hear.</p></div><p class="notice" id="form-notice">Demo submissions are not open yet. Please check back soon.</p><div class="fields">
<label>Your full name<input name="name" placeholder="Your full legal name" autocomplete="name" required maxlength="120"></label>
<label>Email<input name="email" type="email" placeholder="artist@email.com" autocomplete="email" required maxlength="254"></label>
<label>Artist/s<input name="artist" placeholder="Your artist name" required maxlength="160"></label>
<label>Track name<input name="track" placeholder="Your song title" required maxlength="160"></label>
<label class="full">Stream link<input name="stream_link" type="url" placeholder="https://soundcloud.com/your-track" required maxlength="2000"><span style="display:block;margin-top:8px;color:#888;text-transform:none;letter-spacing:0">Use a playable SoundCloud, Dropbox or Google Drive link. Allow link access.</span></label>
<label>Release status<select name="release_status" required><option value="">Select status</option><option>Unreleased</option><option>Already released</option><option>Scheduled for release</option></select></label>
<label>You are applying as<select name="applicant_role" required><option value="">Select your role</option><option>Artist</option><option>Producer</option><option>Manager</option><option>Record label</option><option>Other</option></select></label>
<label class="full">Submission for<select name="submission_for" required><option value="">Choose an opportunity</option><option>Channel feature</option><option>Label release</option><option>Distribution enquiry</option><option>Other collaboration</option></select></label>
<label class="full">More info <span>(optional)</span><textarea name="message" placeholder="Tell us a little about the track and your plans for it." maxlength="5000"></textarea></label>
</div><label class="honeypot" aria-hidden="true">Leave this blank<input name="_gotcha" tabindex="-1" autocomplete="off"></label><label class="consent"><input type="checkbox" name="consent" value="agreed" required><span>I own or have permission to submit this music, and I agree to the <a href="/terms-of-service">Terms of Service</a> and <a href="/privacy-policy">Privacy Policy</a>.</span></label><button class="button" type="submit" id="submit-button" disabled>Submissions opening soon</button><p class="status" id="form-status" role="status" aria-live="polite"></p></form>'''
write('', 'Music that stays with you', '''<section class="hero"><div class="wordmark"><span class="brand-logo"><img src="/lunar4-logo.png" alt="Lunar4" width="1254" height="1254"></span></div><h1>A home for artists.<br>A world of great music.</h1><p>Discover independent sounds, meet the people behind them, and find the songs that stay with you.</p><div class="actions"><a class="button" href="/submit-demo">Submit your demo <span>↗</span></a><a class="button secondary" href="/hall-of-fame">Hall of Fame</a></div><div class="hero-bottom"><span>Music without boundaries</span><span>For the artists. For the listeners.</span><a href="#discover" aria-label="Discover Lunar4">Scroll to explore ↓</a></div></section><section class="intro wrap" id="discover"><div class="eyebrow">Lunar4 Music Group</div><h2>For the song you play again.<br>And the artist you discover next.</h2><p>Different genres. Different places. A shared love of music.</p><div class="genres"><span>Electronic</span><span>Pop</span><span>Indie</span><span>Chill</span><span>Folk & Fusion</span></div></section><section class="feature wrap"><img src="/studio.jpg" alt="A cinematic street scene from a music video" loading="lazy"><div><div class="eyebrow">Made with feeling</div><h2>Every sound<br>has a story.</h2><p>Behind every song is someone with something to say. Lunar4 is a place for those voices, and for listeners who want to hear something new.</p><a class="button secondary" href="/articles">Explore the stories ↗</a></div></section>'''+head('Your music. Our next listen.','Have something to share? Tell us about your track.')+form,False)
write('submit-demo','Submit Your Demo',head('Submit Your Demo','Share your music with Lunar4. Tell us who you are, send a listening link, and let your sound do the talking.',True)+form)
write('contact','Contact',head('Let’s make something<br>worth listening to.','A new release, a collaboration, or a simple hello. Start here.')+'''<section class="contact-grid wrap"><div class="contact-card"><div class="large-mark">01</div><h3>Press & media</h3><p>For interviews, brand assets and stories about Lunar4.</p><div data-contact="press">Contact details coming soon.</div></div><div class="contact-card"><div class="large-mark">02</div><h3>Demos & distribution</h3><p>Have a track ready? Send a listening link and tell us what you have in mind.</p><a class="button secondary" href="/submit-demo">Submit your music ↗</a></div><div class="contact-card"><div class="large-mark">03</div><h3>Stay in the loop</h3><p>New releases, artist stories and moments from behind the music.</p><div data-social="instagramUrl">Social links coming soon.</div></div></section>''',False)
write('hall-of-fame','Hall of Fame',head('Hall of Fame','The songs that become part of your story.',True)+'''<section class="wrap" id="release-list"><div class="empty"><div class="eyebrow">Lunar4 Selects</div><h2>The first chapter<br>is still being written.</h2><p>Our featured releases will appear here. Making something special? We’d love to hear it.</p><a class="button" href="/submit-demo">Send your demo ↗</a></div></section>''')
write('channels','Channels',head('Find your frequency.','Explore the Lunar4 channels. Pick a sound and settle in.')+'''<section class="wrap" id="channel-list"><div class="empty"><h2>New sounds are on the way.</h2><p>Our channel directory is coming soon. Come back for listening links across genres.</p><a class="button secondary" href="/submit-demo">Share your sound ↗</a></div></section>''')
write('merch','Merch',head('Wear your love<br>for the music.','Lunar4 merchandise. Coming soon.')+'''<div class="empty"><div class="brand merch-logo"><span class="brand-logo"><img src="/lunar4-logo.png" alt="Lunar4" width="1254" height="1254"></span></div><p>A little piece of Lunar4, wherever you go.</p><a class="button secondary" href="/">Back to the music ↗</a></div>''',False)
articles=[('welcome-to-lunar4','Welcome to Lunar4','Inside Lunar4','Lunar4','A place for the songs, stories and people behind independent music.', [('A new place for your sound','Lunar4 begins with a simple idea: music is worth discovering. A song can come from a bedroom studio, a late-night recording session, or a melody that arrives when you least expect it.'),('For artists and listeners','This space is for sharing those sounds and the stories behind them. Artists can use our demo page to tell us about a track. Listeners can explore our featured releases as the catalogue grows.'),('Start with a song','If you are working on something you believe in, we would love to hear it. Send a clear listening link and a few words about yourself when submissions open.')]),('prepare-your-demo','Before you send your demo','Artist Guide','01','A short checklist to make your music easy to hear.', [('Make the link easy to open','Share one direct listening link. If the track is private, include the access link and check it in a signed-out browser. Avoid links that need someone to request permission.'),('Tell us the essentials','Include your artist name, track title, release status and a working email address. Let us know whether you want a channel feature, a label release or a conversation about distribution.'),('Keep the sound yours','Only submit music you own or have permission to share. Tell us about collaborators, samples and any existing release commitments.'),('Keep your message simple','A few thoughtful sentences are enough. Explain what the song means to you and what you hope to do with it.')]),('behind-the-song','There is a story behind every song','Perspectives','02','Why the people behind the music matter as much as the finished track.', [('The moment before the music','A voice note. A borrowed instrument. A rhythm tapped on a table. Songs often start quietly, long before the finished recording reaches anyone else.'),('Let the details speak','Sharing those beginnings helps listeners hear a track differently. An instrument, a language or a place can give a song a connection that reaches beyond its genre.'),('Tell your story','When you introduce a release, tell people something real about its making. You do not need a perfect origin story. Sometimes the smallest detail is the one people remember.')])]
cards=''.join(f'''<a class="article-card" href="/articles/{s}" data-article data-title="{t.lower()}" data-order="{i}"><div class="article-art">{art}</div><small>{cat.upper()} · LUNAR4 JOURNAL</small><h3>{t}</h3><p>{desc}</p><span>Read story ↗</span></a>''' for i,(s,t,cat,art,desc,body) in enumerate(articles))
write('articles','Articles & Artist Stories',head('Stories behind<br>the sound.','Artist notes, independent music and life behind the tracks.')+'''<section class="wrap"><div class="toolbar"><input type="search" id="article-search" aria-label="Search articles" placeholder="Search articles"><select id="article-sort" aria-label="Sort articles"><option value="default">Latest first</option><option value="az">Title: A–Z</option><option value="za">Title: Z–A</option></select></div><p id="article-count" role="status">3 articles</p><div class="article-grid" id="article-grid">'''+cards+'''</div><p id="article-empty" class="empty hidden">No articles match your search. Try another word.</p></section>''')
for s,t,cat,art,desc,body in articles:
 write('articles/'+s,t,head(t,cat+' · Lunar4 Journal')+'<article class="document"><p>'+desc+'</p>'+''.join('<h2>'+h+'</h2><p>'+p+'</p>' for h,p in body)+'<p><a href="/articles">← All articles</a></p></article>')
write('privacy-policy','Privacy Policy',head('Privacy Policy')+'''<article class="document"><p class="notice">Draft for owner review. Submissions remain closed until Lunar4’s operator, contact details and data practices are confirmed.</p><h2>Demo information</h2><p>When submissions are enabled, the form will ask for your name, email address, artist name, track details, listening link and any message you choose to include.</p><h2>Purpose</h2><p>The proposed purpose is to review music and respond to enquiries about a feature, release or collaboration. Submitting a demo does not subscribe you to marketing emails.</p><h2>Form processing</h2><p>This site is prepared to use Formspree for submission delivery and storage. No submission is sent while the form is marked closed. Once enabled, the details you submit will be processed by Formspree and the Lunar4 team.</p><h2>Details to confirm before opening</h2><p>Lunar4’s operator must add its legal name, contact address, privacy email, retention period, applicable rights and any relevant international processing information here before accepting submissions.</p><h2>Tracking</h2><p>This website does not add advertising or analytics scripts. The hosting and form providers may process technical information as part of providing their services.</p><h2>Questions</h2><p>Confirmed contact details will appear on the <a href="/contact">Contact page</a>.</p></article>''',False)
write('terms-of-service','Terms of Service',head('Terms of Service')+'''<article class="document"><p class="notice">Draft for owner review. Confirm the business details and final terms before opening submissions.</p><h2>Submitting music</h2><p>Submit only music that you own or are authorised to share. Include accurate contact and track details. Do not send confidential access credentials or unrelated personal information.</p><h2>Review and selection</h2><p>A submission is a request for consideration. It does not guarantee a reply, feature, distribution arrangement or release.</p><h2>Your music stays yours</h2><p>Sending a demo does not transfer ownership of your music. Any release, promotional use or distribution arrangement must be agreed separately with the relevant rights holders.</p><h2>Using this website</h2><p>Do not misuse the submission form, impersonate another artist, or send content you do not have permission to share.</p><h2>Operator and contact details</h2><p>Lunar4’s legal operator, business address, contact email and any jurisdiction-specific terms must be completed before these terms are put into use.</p></article>''',False)
write('setup','Submission Form Setup',head('Connect your<br>submission inbox.','Owner setup guide for Lunar4.')+'''<article class="document"><h2>1. Create your form</h2><p>Open <a href="https://formspree.io/" target="_blank" rel="noopener">Formspree</a>, create an account and create a form named “Lunar4 Demos”. Set the notification email to the inbox where you want demos to arrive and complete any email verification.</p><h2>2. Copy the endpoint</h2><p>Copy the form endpoint from Formspree. It looks like <code>https://formspree.io/f/your-form-id</code>. This is a public form address, not an API secret.</p><h2>3. Connect it to Lunar4</h2><p>Send that endpoint back in this chat and ask to connect it. Or edit <code>dist/config.js</code> in your source:</p><pre>formEndpoint: 'https://formspree.io/f/your-form-id',
contactEmail: 'your actual email address',
legalApproved: true,</pre><p>Only set <code>legalApproved</code> to true after completing the privacy and terms pages with your business details and reviewing the data practices.</p><h2>4. Open submissions</h2><p>Redeploy after updating the configuration. The form will switch from “Submissions opening soon” to “Submit your demo”. Required fields, the permission checkbox, duplicate-click protection and a hidden spam field are already included.</p><h2>5. Test delivery</h2><p>Send a test demo using an email you control and a working music link. Check the Formspree inbox and your notification email, including spam. Confirm that the page shows success only after the service accepts the submission. Delete the test record when finished.</p><h2>Where demos go</h2><p>Submission records live in your Formspree account. Notifications use the recipient configured there. There is no separate Lunar4 database or admin login in this version. Review your provider’s plan limits and spam settings before opening publicly.</p><h2>Audio quality</h2><p>The form sends listening links, not audio uploads. It does not compress or alter your music. Artists can link to the original WAV or other high-quality file hosted on their chosen service.</p><h2>Add your content</h2><p>Use <code>dist/config.js</code> to add your actual channel links, contact email and release catalogue. Original starter articles live in <code>build.py</code>; run it after changing their text. Add your own licensed photography before a public launch. The music video image in this private design preview comes from the reference website.</p><h2>Page coverage</h2><p>Home, Submit Demo, Hall of Fame, Channels, Merch, Articles, article detail pages, Contact, Privacy Policy and Terms of Service are included. The journal uses three original starter stories, rather than republishing the reference site’s article archive. The Hall of Fame is ready for your actual catalogue.</p></article>''',False)
write('404','Page not found',head('This track is missing.','The page you are looking for could not be found.')+'<div class="actions" style="margin-bottom:100px"><a class="button" href="/">Back home</a></div>',False)
(root/'404.html').write_text((root/'404/index.html').read_text())
print('Generated',len(list(root.rglob('*.html'))),'HTML pages')
